from pathlib import Path
import numpy as np,json,sys
O=Path(sys.argv[1]);q=np.load(O/'geometry.npz');v=q['vertices'];t=q['tetrahedra'];p=v[t];D=np.stack([p[:,1]-p[:,0],p[:,2]-p[:,0],p[:,3]-p[:,0]],-1);det=np.linalg.det(D);edge=np.array([np.linalg.norm(p[:,a]-p[:,b],axis=1) for a,b in [(0,1),(0,2),(0,3),(1,2),(1,3),(2,3)]]);qual=12*(abs(det)/2)**(2/3)/(edge**2).sum(0);cond=np.linalg.cond(D);ids=np.argsort(qual)[:20];r={'quality_quantiles':np.quantile(qual,[0,.001,.01,.1,.5,1]).tolist(),'condition_quantiles':np.quantile(cond,[0,.5,.9,.99,.999,1]).tolist(),'quality_below_001':int((qual<.001).sum()),'worst':[{'tet':int(i),'quality':float(qual[i]),'condition':float(cond[i]),'center':p[i].mean(0).tolist(),'indices':t[i].tolist()} for i in ids]};print(json.dumps(r,indent=2));(O/'quality_report.json').write_text(json.dumps(r,indent=2))
